        char = 'W' if char == 'b' else 'b'
    elif char in 'cC':
        char = 'b' if char == 'c' else 'C'

    board[row][col] = char

    if char == 'B':
        for i in range(max(0, row-1), min(64, row+2)):
            for j in range(max(0, col-1), min(64, col+2)):
                if board[i][j] in 'bB':
                    board[i][j] = 'W'
    elif char == 'W':
        for i in range(max(0, row-1), min(64, row+2)):
            for j in range(max(0, col-1), min(64, col+2)):
                if board[i][j] in 'bB':
                    board[i][j] = 'b'
    elif char == 'cC':
        for i in range(max(0, row-1), min(64, row+2)):
